const staticData = $getWorkflowStaticData('global');
const config = $('Config').first().json;
const input = $input.first().json || {};
let failure = {};
let preparedFailurePresent = false;
try {
  failure = $('Prepare Locked Offer Failure').first().json || {};
  preparedFailurePresent = Object.keys(failure).length > 0;
} catch (error) {
  failure = {};
}
const source = preparedFailurePresent ? failure : input;
let deliveryHandoff = input && typeof input.delivery === 'object' ? input.delivery : null;
if (!deliveryHandoff) {
  try {
    const offerResult = $('Create NEONTRIP Offer').first().json || {};
    deliveryHandoff = offerResult && typeof offerResult.delivery === 'object' ? offerResult.delivery : null;
  } catch (error) {
    deliveryHandoff = null;
  }
}
const deliveryHandoffAccepted = Boolean(deliveryHandoff && ['ready', 'wait', 'paused', 'skip'].includes(String(deliveryHandoff.action || '')));
const currentLeaseCardId = staticData.kiVideoLeaseCardId || '';
const shouldRelease = !currentLeaseCardId || currentLeaseCardId === config.cardId;

if (shouldRelease) {
  staticData.kiVideoLeaseUntil = null;
  staticData.kiVideoLeaseCardId = null;
  staticData.kiVideoLeaseCardName = null;
  staticData.kiVideoLeaseAcquiredAt = null;
}

let sent = deliveryHandoffAccepted;
try {
  if (!sent) sent = $('Preview Delivery OK?').first().json.ok === true;
} catch (error) {
  sent = false;
}

let auditWriteOk = null;
let auditWriteError = null;
try {
  const auditResult = $('Audit: Company Brain Offer Failure').first().json || {};
  auditWriteOk = !auditResult.error;
  auditWriteError = auditResult.error ? JSON.stringify(auditResult.error).slice(0, 1000) : null;
} catch (error) {
  auditWriteOk = null;
}

const serialized = JSON.stringify(source).slice(0, 4000);
const retryable = source.retryable === true;
const rateLimited = source.rateLimited === true || /\b429\b|rate limit|too many requests/i.test(serialized);
const transientProviderFailure =
  source.transientVideoProviderFailure === true ||
  /\b50[0234]\b|econnrefused|econnreset|etimedout|upstream connect|connection refused|temporar(?:y|ily)|overloaded|service unavailable|try again later/i.test(serialized);
const previewDeliveryRejected = source.ok === false;
const currentAttempt = Math.max(1, Number(source.currentAttempt || config.jobAttempts || 1));
const jobMaxAttempts = Math.max(1, Number(config.jobMaxAttempts || 2));
const directRetryable =
  (rateLimited || transientProviderFailure || previewDeliveryRejected) &&
  currentAttempt < jobMaxAttempts;
const shouldRetry = preparedFailurePresent ? retryable : directRetryable;
const failed = !sent && !shouldRetry;
const jobStatus = sent ? 'sent' : (shouldRetry ? 'retry' : 'failed');
const errorCode = sent ? null : (
  source.failureType ||
  source.failureCode ||
  source.errorCode ||
  (rateLimited
    ? 'rate_limited'
    : (transientProviderFailure
      ? 'transient_video_provider_failure'
      : (previewDeliveryRejected ? 'preview_delivery_rejected' : 'preview_delivery_failed')))
);
const errorMessage = sent ? null : (
  source.failureMessage ||
  source.errorMessage ||
  source.mockupError ||
  source.reason ||
  serialized.slice(0, 1000) ||
  'Preview delivery did not complete successfully'
);

return [{
  json: {
    leaseReleased: shouldRelease,
    releasedCardId: config.cardId,
    previousLeaseCardId: currentLeaseCardId || null,
    releasedAt: new Date().toISOString(),
    jobId: config.jobId || null,
    claimToken: config.claimToken || null,
    previewDeliveryJobStatus: jobStatus,
    previewDeliveryJobErrorCode: errorCode,
    previewDeliveryJobErrorMessage: errorMessage,
    previewDeliveryJobFailed: failed,
    automaticRetryPlanned: shouldRetry,
    currentAttempt,
    nextAttempt: shouldRetry ? (source.nextAttempt || currentAttempt + 1) : null,
    automaticRecoveryKind: source.automaticRecoveryKind || (shouldRetry ? 'infrastructure_retry' : 'manual_review'),
    automaticRecoveryAttemptLimit: source.automaticRecoveryAttemptLimit || jobMaxAttempts,
    automaticVideoAttemptLimit: source.automaticVideoAttemptLimit || 2,
    videoQcIssues: source.videoQcIssues || [],
    videoQcConfidence: source.videoQcConfidence ?? null,
    videoGenerationFingerprint: source.videoGenerationFingerprint || null,
    videoGenerationMode: source.videoGenerationMode || null,
    offerDeliveryHandoffAccepted: deliveryHandoffAccepted,
    offerDeliveryAction: deliveryHandoff ? String(deliveryHandoff.action || '') : null,
    offerDeliveryStatus: deliveryHandoff ? String(deliveryHandoff.status || '') : null,
    auditWriteOk,
    auditWriteError,
    rawError: source.rawError || serialized.slice(0, 1500),
  }
}];

