const input = $input.first().json || {};
const serialized = JSON.stringify(input).slice(0, 12000);
const haystack = serialized.toLowerCase();

const isRateLimit =
  /\b429\b/.test(serialized) ||
  haystack.includes('rate limit') ||
  haystack.includes('too many requests') ||
  haystack.includes('trello request failed with 429');

const isCardChangedAfterPreflight = haystack.includes('card_changed_after_preflight');
const isLockedOffer =
  !isCardChangedAfterPreflight &&
  (/viewed offers are locked|cannot be re-imported/i.test(serialized) ||
    (/\b409\b/.test(serialized) && !haystack.includes('card_changed_after_preflight')));

const isTransientInfrastructureFailure =
  /\b50[0234]\b/.test(serialized) ||
  /econnrefused|econnreset|etimedout|upstream connect|connection refused|socket hang up|temporar(?:y|ily)|overloaded|service unavailable|try again later/i.test(serialized);

const config = $('Config').first().json;
const jobAttempts = Math.max(1, Number(config.jobAttempts || 1));
const jobMaxAttempts = Math.max(1, Number(config.jobMaxAttempts || 2));
const automaticVideoAttemptLimit = Math.min(2, jobMaxAttempts);
const rawName = String(config.cardName || '').trim();
const cleanName = rawName.replace(/^fehler\s*[-:]\s*/i, '').trim() || rawName || config.cardId;
const newName = /^fehler\b/i.test(rawName) ? rawName : 'FEHLER - ' + cleanName;

let executionId = '';
try {
  executionId = String($execution.id || '');
} catch (error) {
  executionId = '';
}

const upstreamFailureType = String(input.failureType || '').trim();
const upstreamFailureMessage = String(input.failureMessage || input.reason || '').trim();

let offerResponse = input;
try {
  const createdOffer = $('Create NEONTRIP Offer').first().json || {};
  if (createdOffer && typeof createdOffer === 'object' && Object.keys(createdOffer).length) offerResponse = createdOffer;
} catch (error) {
  // The offer node may not have run on earlier failure paths.
}
const delivery = offerResponse && typeof offerResponse.delivery === 'object' ? offerResponse.delivery : null;
const deliveryAction = String(delivery && delivery.action || '').trim().toLowerCase();
const deliveryStatus = String(delivery && delivery.status || '').trim().toUpperCase();
const deliveryReason = String(delivery && delivery.reason || '').trim();
const deliveryBlockers = Array.isArray(delivery && delivery.readiness && delivery.readiness.blockers)
  ? delivery.readiness.blockers.map(value => String(value || '').trim()).filter(Boolean)
  : [];
const deliveryBlocked = deliveryAction === 'blocked' || deliveryStatus === 'FAILED';
const invalidCustomerDelivery = deliveryBlocked && /customer_email_invalid_or_internal|customer_email_missing_or_invalid|customer_data_invalid/i.test(
  [deliveryReason, ...deliveryBlockers].join(' ')
);

let customer = {};
try {
  customer = $('Validate Preview Customer').first().json || {};
} catch (error) {
  customer = {};
}
const customerName = String(customer.displayName || [customer.firstName, customer.lastName].filter(Boolean).join(' ') || customer.company || '').trim();
const customerEmail = String(customer.emailRaw || offerResponse.customerEmail || customer.email || '').trim();
const customerPhone = String(customer.phoneRaw || offerResponse.customerPhone || customer.phone || '').trim();
const emailValid = customer.emailValid === true || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail.toLowerCase());
const phoneDigits = customerPhone.replace(/\D/g, '');
const phoneValid = customer.phoneValid === true || (phoneDigits.length >= 7 && phoneDigits.length <= 15);
const nameValid = customer.nameValid === true || customerName.length >= 2;
const customerDataMessage = [
  'Kundendaten pruefen - Angebot wurde NICHT versendet.',
  'Name: ' + (customerName || '[fehlt]') + ' - ' + (nameValid ? 'vorhanden' : 'ungueltig/zu kurz'),
  'E-Mail: ' + (customerEmail || '[fehlt]') + ' - ' + (emailValid ? 'gueltig' : 'ungueltig'),
  'Telefon: ' + (customerPhone || '[fehlt]') + ' - ' + (phoneValid ? 'plausibel' : 'ungueltig/zu kurz'),
  'Handlung: Kundendaten in der Datenbank bzw. Leadquelle korrigieren und danach einen neuen Versandlauf freigeben.'
].join('\n');

let failureType = upstreamFailureType || 'neontrip_offer_failed';
let failureMessage = upstreamFailureMessage || 'Angebot wurde nicht rausgeschickt. Die Offer-Erstellung ist fehlgeschlagen.';

if (!upstreamFailureType && deliveryBlocked) {
  failureType = invalidCustomerDelivery
    ? 'preview_delivery_customer_data_invalid'
    : 'offer_delivery_handoff_blocked';
  failureMessage = invalidCustomerDelivery
    ? customerDataMessage
    : 'Angebotsversand wurde von der Offers-App blockiert: ' + (deliveryReason || deliveryBlockers.join(', ') || 'fachliche Versandpruefung fehlgeschlagen') + '.';
} else if (!upstreamFailureType && isCardChangedAfterPreflight) {
  failureType = 'offer_card_changed_after_preflight';
  failureMessage = 'Die Karte wurde waehrend der Verarbeitung geaendert. Der aktuelle Stand wird ohne neue Videokosten erneut vorgeprueft.';
} else if (!upstreamFailureType && isLockedOffer) {
  failureType = 'neontrip_offer_locked';
  failureMessage = 'Angebot ist bereits angesehen/gesperrt und kann nicht erneut aus Trello importiert werden.';
} else if (!upstreamFailureType && isRateLimit) {
  failureType = 'neontrip_offer_trello_rate_limited';
  failureMessage = 'Angebot wurde noch nicht rausgeschickt. Trello/Offer-API ist rate-limited und wird automatisch erneut versucht.';
} else if (!upstreamFailureType && isTransientInfrastructureFailure) {
  failureType = 'neontrip_offer_transient_failure';
  failureMessage = 'Angebot wurde noch nicht rausgeschickt. Eine voruebergehende API-/Netzwerkstoerung wird automatisch erneut versucht.';
}

const previewErrors = Array.isArray(input.errors)
  ? input.errors.map((entry) => String(entry || '').trim()).filter(Boolean)
  : [];
const previewPreSendBlocked = input.ok === false && input.blocked === true;
const permanentCustomerDataFailure = previewErrors.some((entry) =>
  /customer_email_missing_or_invalid|customer_not_in_live_canary/i.test(entry)
);
if (!upstreamFailureType && previewPreSendBlocked) {
  failureType = permanentCustomerDataFailure
    ? 'preview_delivery_customer_data_invalid'
    : 'preview_delivery_pre_send_blocked';
  failureMessage = permanentCustomerDataFailure
    ? customerDataMessage
    : 'Kundenversand wurde vor dem Senden blockiert (' + (previewErrors.join(', ') || 'Payload-Pruefung') + '). Der sichere Vorversand-Schritt wird erneut aufgebaut.';
}

const videoQcFailure = failureType === 'video_content_qc_failed' || failureType === 'video_content_qc_unavailable' || failureType === 'video_content_qc_inconclusive';
const retryableVideoQc = videoQcFailure && jobAttempts < automaticVideoAttemptLimit;
const retryableInfrastructure =
  (isRateLimit || isTransientInfrastructureFailure) &&
  jobAttempts < jobMaxAttempts;
const retryablePreSend =
  previewPreSendBlocked &&
  !permanentCustomerDataFailure &&
  jobAttempts < jobMaxAttempts;
const retryableCardChanged = isCardChangedAfterPreflight && jobAttempts < jobMaxAttempts;
const retryable = retryableVideoQc || retryableInfrastructure || retryablePreSend || retryableCardChanged;
const automaticRecoveryKind = retryableVideoQc
  ? 'video_regeneration'
  : (retryableInfrastructure
    ? 'infrastructure_retry'
    : (retryablePreSend
      ? 'pre_send_rebuild'
      : (retryableCardChanged ? 'fresh_preflight_retry' : 'manual_review')));
const videoQcIssues = Array.isArray(input.videoContentQcIssues) ? input.videoContentQcIssues : [];
const videoQcConfidence = Number.isFinite(Number(input.videoContentQcConfidence))
  ? Number(input.videoContentQcConfidence)
  : null;
let videoGenerationFingerprint = null;
let videoGenerationMode = jobAttempts >= 2 ? 'locked_static_retry' : 'cinematic_standard';
try {
  videoGenerationFingerprint = $('Check Reusable Trello Video').first().json.videoGenerationFingerprint || null;
} catch (error) {
  videoGenerationFingerprint = null;
}
try {
  videoGenerationMode = $('Build Runway Request').first().json.videoGenerationMode || videoGenerationMode;
} catch (error) {
  // Keep the deterministic attempt-based fallback when generation did not start.
}

return [{ json: {
  cardId: config.cardId,
  cardName: rawName,
  cardUrl: config.cardUrl || ('https://trello.com/c/' + config.cardId),
  newName,
  quoteReadyListId: '659ffc4e5f8bffd67fe38265',
  failureType,
  failureMessage,
  executionId,
  rawError: serialized.slice(0, 1500),
  retryable,
  automaticRetryPlanned: retryable,
  currentAttempt: jobAttempts,
  nextAttempt: retryable ? jobAttempts + 1 : null,
  automaticVideoAttemptLimit,
  automaticRecoveryAttemptLimit: retryableVideoQc ? automaticVideoAttemptLimit : jobMaxAttempts,
  automaticRecoveryKind,
  previewDeliveryErrors: previewErrors,
  videoQcIssues,
  videoQcConfidence,
  videoGenerationFingerprint,
  videoGenerationMode,
  customerCommunicationSent: false,
  handledAt: new Date().toISOString()
} }];

