const card = $input.first().json || {};
const config = $('Config').first().json || {};
const labels = Array.isArray(card.labels) ? card.labels.map((label) => String(label.name || '').trim()).filter(Boolean) : [];

const blockingPatterns = [
  /video.*(prüf|pruef|fehler|fail|abweichung|stop|problem)/i,
  /^\s*fehler\b/i,
  /angebot.*nicht.*senden/i
