  reason = 'Die automatische Ähnlichkeitsprüfung erreichte ' + Math.round(confidence * 100) + ' %. Benötigt werden mindestens 70 %. Das System konnte deshalb nicht sicher genug bestätigen, dass Video und Mockup übereinstimmen.';
} else {
  reason = provider.reason || provider.errorMessage || provider.videoOmittedReason || 'Das Video konnte nach den automatischen Versuchen nicht zuverlässig erstellt oder geprüft werden.';
}
return '🎬 KI-VIDEO VERSUCH ' + Math.min(attempt, limit) + '/' + limit + ' VERWORFEN — ENDSTATUS OHNE VIDEO\n\n' +
  'Versuche: ' + Math.min(attempt, limit) + '/' + limit + ' abgeschlossen\n' +
  'Geprüftes Eingabe-Mockup: ' + mockup + '\n' +
  'Verworfenes Ergebnis: KI-Video aus dem letzten Versuch\n' +
  'Grund: ' + reason + '\n\n' +
  'Ergebnis: Kein verworfenes Video wurde an der Karte belassen. Das Angebot wird kontrolliert ohne Video weitergeführt.\n' +
  'Hinweis: Dieser Statuskommentar löst keine Kundenmail aus.\n' +
  'Queue-Job: ' + (config.jobId || '-');
})() }}
